import { OLBridge } from './fences/OLBridge.ts';
import { OLBreakdown } from './fences/OLBreakdown.ts';
import { OLChorus } from './fences/OLChorus.ts';
import { OLConfig } from './fences/OLConfig.ts';
import {
  OLFenceDefinition,
  formatDeclaredPartName,
} from './fences/OLFenceDefinition.ts';
import { OLFinalChorus } from './fences/OLFinalChorus.ts';
import { OLFenceRegistry } from './fences/OLFenceRegistry.ts';
import { OLFreeTextFence } from './fences/OLFreeTextFence.ts';
import { OLInstrumental } from './fences/OLInstrumental.ts';
import { OLInstrumentalFence } from './fences/OLInstrumentalFence.ts';
import { OLInterlude } from './fences/OLInterlude.ts';
import { OLIntro } from './fences/OLIntro.ts';
import { OLLyricFence } from './fences/OLLyricFence.ts';
import { OLNote } from './fences/OLNote.ts';
import { OLOutro } from './fences/OLOutro.ts';
import { OLPostChorus } from './fences/OLPostChorus.ts';
import { OLPreChorus } from './fences/OLPreChorus.ts';
import { OLRefrain } from './fences/OLRefrain.ts';
import { OLSolo } from './fences/OLSolo.ts';
import { OLTag } from './fences/OLTag.ts';
import { OLVamp } from './fences/OLVamp.ts';
import { OLVerse } from './fences/OLVerse.ts';

const types = {
  OLFenceDefinition,
  OLConfig,
  OLIntro,
  OLFinalChorus,
  OLPreChorus,
  OLPostChorus,
  OLRefrain,
  OLBridge,
  OLChorus,
  OLVerse,
  OLNote,
  OLTag,
  OLOutro,
  OLInstrumental,
  OLInterlude,
  OLBreakdown,
  OLVamp,
  OLSolo,
};

const definitions = [
  new OLConfig(),
  new OLIntro(),
  new OLFinalChorus(),
  new OLPreChorus(),
  new OLPostChorus(),
  new OLRefrain(),
  new OLBridge(),
  new OLChorus(),
  new OLVerse(),
  new OLNote(),
  new OLTag(),
  new OLOutro(),
  new OLInstrumental(),
  new OLInterlude(),
  new OLBreakdown(),
  new OLVamp(),
  new OLSolo(),
];

const registry = new OLFenceRegistry(definitions);
const definitionsByClassName = Object.fromEntries(
  definitions.map((definition) => [definition.className, definition]),
);

const parser = {
  types,
  registry,
  definitions: registry.getDefinitions(),
  definitionsByClassName,
  findFenceDefinition: (header) => registry.findByHeader(header),
  parseFenceHeader: (info) => registry.parseHeader(info),
  getFenceBlockKind: (info) => registry.getFenceBlockKind(info),
  getFenceHeaderError: (info) => registry.getFenceHeaderError(info),
  getFenceSnippetDefinitions: () => registry.getSnippetDefinitions(),
  getRequiredDeclaredPartNames: () => registry.getRequiredDeclaredPartNames(),
  formatDeclaredPartName,
};

function findFenceDefinition(header) {
  return registry.findByHeader(header);
}

function parseFenceHeader(info) {
  return registry.parseHeader(info);
}

function getFenceBlockKind(info) {
  return registry.getFenceBlockKind(info);
}

function getFenceHeaderError(info) {
  return registry.getFenceHeaderError(info);
}

function getFenceSnippetDefinitions() {
  return registry.getSnippetDefinitions();
}

function getRequiredDeclaredPartNames() {
  return registry.getRequiredDeclaredPartNames();
}

export {
  OLBridge,
  OLBreakdown,
  OLChorus,
  OLConfig,
  OLFenceDefinition,
  OLFinalChorus,
  OLFreeTextFence,
  OLInstrumental,
  OLInstrumentalFence,
  OLInterlude,
  OLIntro,
  OLLyricFence,
  OLNote,
  OLOutro,
  OLPostChorus,
  OLPreChorus,
  OLRefrain,
  OLSolo,
  OLTag,
  OLVamp,
  OLVerse,
  definitions,
  definitionsByClassName,
  findFenceDefinition,
  formatDeclaredPartName,
  getFenceBlockKind,
  getFenceHeaderError,
  getFenceSnippetDefinitions,
  getRequiredDeclaredPartNames,
  parseFenceHeader,
  parser,
  registry,
  types,
};
