import { OLFenceDefinition } from './OLFenceDefinition.ts';

class OLLyricFence extends OLFenceDefinition {
  constructor(options) {
    super({
      ...options,
      kind: 'lyric',
      tokenState: 'olLyric',
    });
  }

  validateBody(context) {
    context.validators.validateLyricBlock(
      context.bodyLines,
      context.startLineNumber,
      context.markers,
    );
  }

  renderPreviewBody(context) {
    return context.helpers.renderLyricLineCollection(context.lineEntries);
  }
}

export { OLLyricFence };
