import {
  DEFAULT_EDITOR_MODE,
  DEFAULT_PANEL_VISIBILITY,
  DEFAULT_THEME,
  DRAFT_STORAGE_KEY,
  LEGACY_THEME_STORAGE_KEY,
  THEME_STORAGE_KEY,
} from '../shared.ts';
import { isOpenLyricTheme } from '../../components/internal/theme.ts';
import { FULL_EDITOR_SHELL_MODE, getEditorShellMode } from '../page-config.ts';
import {
  loadOpenLyricPluginEnabledPreference,
  normalizeOpenLyricPluginEnabledPreference,
  saveOpenLyricPluginEnabledPreference,
} from '../open-lyric-plugin-preference.ts';
import {
  normalizeLanguageCode,
  normalizeSpellcheckLookupWord,
} from '../spellcheck-common.ts';

const INVISIBLE_CHARACTERS_STORAGE_KEY =
  'open-lyric-editor-invisible-characters';
const PANEL_VISIBILITY_STORAGE_KEY = 'open-lyric-editor-panel-visibility';
const PANEL_SIZES_STORAGE_KEY = 'open-lyric-editor-panel-size';
const LEGACY_SPELLCHECK_STORAGE_KEY = 'open-lyric-editor-spellcheck';
const SPELLCHECK_STORAGE_KEY_PREFIX = 'open-lyric-editor-spellcheck-';
const SPELLCHECK_PREFERENCES_VERSION_STORAGE_KEY =
  'open-lyric-editor-spellcheck-version';
const SPELLCHECK_PREFERENCES_VERSION = 'separate-language-v1';
const SPELLCHECK_CUSTOM_DICTIONARY_STORAGE_KEY_PREFIX =
  'open-lyric-editor-spellcheck-custom-dictionary-';
const SPELLCHECK_CUSTOM_DICTIONARY_VERSION_STORAGE_KEY =
  'open-lyric-editor-spellcheck-custom-dictionary-version';
const LEGACY_SPELLCHECK_CUSTOM_DICTIONARY_VERSION = 'per-language-v1';
const SPELLCHECK_CUSTOM_DICTIONARY_VERSION = 'per-language-v2';
const SPELLCHECK_EXCLUDED_WORDS_STORAGE_KEY_PREFIX =
  'open-lyric-editor-spellcheck-excluded-words-';
const SPELLCHECK_EXCLUDED_WORDS_VERSION_STORAGE_KEY =
  'open-lyric-editor-spellcheck-excluded-words-version';
const SPELLCHECK_EXCLUDED_WORDS_VERSION = 'per-language-v1';
const PREVIEW_TYPOGRAPHY_STORAGE_KEY = 'open-lyric-editor-preview-typography';
const EDITOR_MODE_STORAGE_KEY = 'open-lyric-editor-mode';
const AUTO_SUGGEST_STORAGE_KEY = 'open-lyric-editor-auto-suggest';
const WORD_WRAP_STORAGE_KEY = 'open-lyric-editor-word-wrap';
const TRANSCRIPT_LOCALE_STORAGE_KEY = 'open-lyric-editor-transcript-locale';
const TRANSCRIPT_UPLOAD_API_KEY_STORAGE_KEY =
  'open-lyric-editor-transcript-upload-api-key';
const KEYBOARD_WINDOW_STORAGE_KEY_PREFIX = 'open-lyric-editor-keyboard-window-';
const DEFAULT_PANEL_SIZE_WEIGHT = 1;
const MIN_PREVIEW_FONT_SIZE_PX = 12;
const MAX_PREVIEW_FONT_SIZE_PX = 36;
const DEFAULT_PREVIEW_TYPOGRAPHY = Object.freeze({
  fontSizePx: 16,
  fontFamily: '',
});

function getShellScopedStorageKey(storageKey) {
  return getEditorShellMode() === FULL_EDITOR_SHELL_MODE
    ? storageKey
    : `${storageKey}-${getEditorShellMode()}`;
}

function getBrowserStorage(storageName) {
  try {
    return globalThis[storageName] ?? null;
  } catch (_error) {
    return null;
  }
}

/**
 * Owns browser persistence for the editor shell so controllers do not each
 * duplicate localStorage keys, fallback rules, or normalization logic.
 */
class EditorPreferencesStore {
  constructor(
    storage = getBrowserStorage('localStorage'),
    draftStorage = getBrowserStorage('sessionStorage'),
    persistentDraftStorage = storage,
  ) {
    this.storage = storage;
    this.draftStorage = draftStorage;
    this.persistentDraftStorage = persistentDraftStorage;
  }

  getDefaultPanelSizeWeight() {
    return DEFAULT_PANEL_SIZE_WEIGHT;
  }

  normalizePanelVisibilityPreference(value) {
    const normalizedValue =
      value && typeof value === 'object' ? value : DEFAULT_PANEL_VISIBILITY;

    const panelVisibility = {
      editorVisible:
        typeof normalizedValue.editorVisible === 'boolean'
          ? normalizedValue.editorVisible
          : DEFAULT_PANEL_VISIBILITY.editorVisible,
      previewVisible:
        typeof normalizedValue.previewVisible === 'boolean'
          ? normalizedValue.previewVisible
          : DEFAULT_PANEL_VISIBILITY.previewVisible,
      openLyricVisible:
        typeof normalizedValue.openLyricVisible === 'boolean'
          ? normalizedValue.openLyricVisible
          : DEFAULT_PANEL_VISIBILITY.openLyricVisible,
    };

    if (
      !panelVisibility.editorVisible &&
      !panelVisibility.previewVisible &&
      !panelVisibility.openLyricVisible
    ) {
      return {
        ...DEFAULT_PANEL_VISIBILITY,
      };
    }

    return panelVisibility;
  }

  loadPanelVisibilityPreference() {
    try {
      const rawValue = this.storage?.getItem(
        getShellScopedStorageKey(PANEL_VISIBILITY_STORAGE_KEY),
      );
      if (!rawValue) {
        return null;
      }

      return this.normalizePanelVisibilityPreference(JSON.parse(rawValue));
    } catch (_error) {
      return null;
    }
  }

  savePanelVisibilityPreference(value) {
    try {
      this.storage?.setItem(
        getShellScopedStorageKey(PANEL_VISIBILITY_STORAGE_KEY),
        JSON.stringify(this.normalizePanelVisibilityPreference(value)),
      );
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  normalizePanelSizeWeights(value) {
    if (typeof value === 'number') {
      const editorWeight = Math.min(Math.max(value, 1), 99);

      return {
        editor: editorWeight,
        preview: Math.max(100 - editorWeight, 1),
        openLyric: DEFAULT_PANEL_SIZE_WEIGHT,
      };
    }

    const normalizedValue = value && typeof value === 'object' ? value : {};

    return {
      editor:
        Number.isFinite(Number(normalizedValue.editor)) &&
        Number(normalizedValue.editor) > 0
          ? Number(normalizedValue.editor)
          : DEFAULT_PANEL_SIZE_WEIGHT,
      preview:
        Number.isFinite(Number(normalizedValue.preview)) &&
        Number(normalizedValue.preview) > 0
          ? Number(normalizedValue.preview)
          : DEFAULT_PANEL_SIZE_WEIGHT,
      openLyric:
        Number.isFinite(Number(normalizedValue.openLyric)) &&
        Number(normalizedValue.openLyric) > 0
          ? Number(normalizedValue.openLyric)
          : DEFAULT_PANEL_SIZE_WEIGHT,
    };
  }

  loadPanelSizePreference() {
    try {
      const rawValue = this.storage?.getItem(
        getShellScopedStorageKey(PANEL_SIZES_STORAGE_KEY),
      );
      if (!rawValue) {
        return null;
      }

      return this.normalizePanelSizeWeights(JSON.parse(rawValue));
    } catch (_error) {
      return null;
    }
  }

  savePanelSizePreference(panelSizeWeights) {
    try {
      this.storage?.setItem(
        getShellScopedStorageKey(PANEL_SIZES_STORAGE_KEY),
        JSON.stringify(this.normalizePanelSizeWeights(panelSizeWeights)),
      );
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  normalizeDraftRecord(value) {
    if (!value || typeof value.content !== 'string') {
      return null;
    }

    return {
      content: value.content,
      fileName:
        typeof value.fileName === 'string' && value.fileName.trim()
          ? value.fileName
          : 'untitled.md',
      sharedDocumentDate:
        typeof value.sharedDocumentDate === 'string' &&
        value.sharedDocumentDate.trim()
          ? value.sharedDocumentDate.trim()
          : '',
      updatedAt:
        Number.isFinite(Number(value.updatedAt)) && Number(value.updatedAt) > 0
          ? Number(value.updatedAt)
          : 0,
    };
  }

  loadDraftFromStorage(storage) {
    try {
      const rawValue = storage?.getItem(DRAFT_STORAGE_KEY);
      if (!rawValue) {
        return null;
      }

      return this.normalizeDraftRecord(JSON.parse(rawValue));
    } catch (_error) {
      return null;
    }
  }

  getPreferredDraftRecord(sessionDraft, persistentDraft) {
    if (!sessionDraft) {
      return persistentDraft;
    }

    if (!persistentDraft) {
      return sessionDraft;
    }

    if (persistentDraft.updatedAt > sessionDraft.updatedAt) {
      return persistentDraft;
    }

    return sessionDraft;
  }

  saveDraftToStorage(storage, draftRecord) {
    if (!storage) {
      return;
    }

    try {
      storage.setItem(DRAFT_STORAGE_KEY, JSON.stringify(draftRecord));
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  syncDraftRecord(draftRecord) {
    if (!draftRecord) {
      return;
    }

    this.saveDraftToStorage(this.draftStorage, draftRecord);

    if (this.persistentDraftStorage !== this.draftStorage) {
      this.saveDraftToStorage(this.persistentDraftStorage, draftRecord);
    }
  }

  clearDraftStorage(storage) {
    if (!storage) {
      return;
    }

    try {
      storage.removeItem(DRAFT_STORAGE_KEY);
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  loadDraft() {
    const sessionDraft = this.loadDraftFromStorage(this.draftStorage);
    const persistentDraft = this.loadDraftFromStorage(
      this.persistentDraftStorage,
    );
    const draftRecord = this.getPreferredDraftRecord(
      sessionDraft,
      persistentDraft,
    );

    if (!draftRecord) {
      return null;
    }

    this.syncDraftRecord(draftRecord);
    return draftRecord;
  }

  saveDraft(content, fileName, { sharedDocumentDate = '' } = {}) {
    const draftRecord = {
      content,
      fileName,
      sharedDocumentDate:
        typeof sharedDocumentDate === 'string' ? sharedDocumentDate.trim() : '',
      updatedAt: Date.now(),
    };

    this.syncDraftRecord(draftRecord);
  }

  clearDraft() {
    this.clearDraftStorage(this.draftStorage);

    if (this.persistentDraftStorage !== this.draftStorage) {
      this.clearDraftStorage(this.persistentDraftStorage);
    }
  }

  loadInvisibleCharacterPreference() {
    try {
      const storedValue = this.storage?.getItem(
        INVISIBLE_CHARACTERS_STORAGE_KEY,
      );

      if (storedValue !== '1' && storedValue !== '0') {
        return null;
      }

      return storedValue === '1';
    } catch (_error) {
      return null;
    }
  }

  saveInvisibleCharacterPreference(enabled) {
    try {
      this.storage?.setItem(
        INVISIBLE_CHARACTERS_STORAGE_KEY,
        enabled ? '1' : '0',
      );
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  loadAutoSuggestPreference() {
    try {
      const storedValue = this.storage?.getItem(AUTO_SUGGEST_STORAGE_KEY);

      if (storedValue !== '1' && storedValue !== '0') {
        return true;
      }

      return storedValue === '1';
    } catch (_error) {
      return true;
    }
  }

  saveAutoSuggestPreference(enabled) {
    try {
      this.storage?.setItem(AUTO_SUGGEST_STORAGE_KEY, enabled ? '1' : '0');
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  getKeyboardWindowStorageKey(keyboardId) {
    const normalizedKeyboardId = String(keyboardId || '')
      .trim()
      .toLowerCase();

    if (!normalizedKeyboardId) {
      return '';
    }

    return `${KEYBOARD_WINDOW_STORAGE_KEY_PREFIX}${normalizedKeyboardId}`;
  }

  normalizeKeyboardWindowPreference(value) {
    const normalizedValue = value && typeof value === 'object' ? value : {};
    const normalizedPositionValue =
      normalizedValue.position && typeof normalizedValue.position === 'object'
        ? normalizedValue.position
        : null;
    const normalizedSizeValue =
      normalizedValue.size && typeof normalizedValue.size === 'object'
        ? normalizedValue.size
        : null;
    const left = Number(normalizedPositionValue?.left);
    const top = Number(normalizedPositionValue?.top);
    const width = Number(normalizedSizeValue?.width);
    const height = Number(normalizedSizeValue?.height);

    return {
      isMinimized: Boolean(normalizedValue.isMinimized),
      isOpen: Boolean(normalizedValue.isOpen),
      position:
        Number.isFinite(left) && Number.isFinite(top)
          ? {
              left: Math.round(left),
              top: Math.round(top),
            }
          : null,
      size:
        Number.isFinite(width) &&
        width > 0 &&
        Number.isFinite(height) &&
        height > 0
          ? {
              height: Math.round(height),
              width: Math.round(width),
            }
          : null,
    };
  }

  loadKeyboardWindowPreference(keyboardId) {
    const storageKey = this.getKeyboardWindowStorageKey(keyboardId);

    if (!storageKey) {
      return null;
    }

    try {
      const rawValue = this.storage?.getItem(storageKey);

      if (!rawValue) {
        return null;
      }

      return this.normalizeKeyboardWindowPreference(JSON.parse(rawValue));
    } catch (_error) {
      return null;
    }
  }

  saveKeyboardWindowPreference(keyboardId, value) {
    const storageKey = this.getKeyboardWindowStorageKey(keyboardId);

    if (!storageKey) {
      return;
    }

    try {
      this.storage?.setItem(
        storageKey,
        JSON.stringify(this.normalizeKeyboardWindowPreference(value)),
      );
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  normalizeWordWrapPreference(value) {
    return value === 'off' ? 'off' : 'on';
  }

  loadWordWrapPreference() {
    try {
      return this.normalizeWordWrapPreference(
        this.storage?.getItem(WORD_WRAP_STORAGE_KEY),
      );
    } catch (_error) {
      return this.normalizeWordWrapPreference(null);
    }
  }

  saveWordWrapPreference(value) {
    try {
      this.storage?.setItem(
        WORD_WRAP_STORAGE_KEY,
        this.normalizeWordWrapPreference(value),
      );
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  normalizeSpellcheckLanguage(languageCode) {
    return normalizeLanguageCode(languageCode);
  }

  getSpellcheckStorageKey(languageCode) {
    return `${SPELLCHECK_STORAGE_KEY_PREFIX}${languageCode}`;
  }

  getSpellcheckCustomDictionaryStorageKey(languageCode) {
    return `${SPELLCHECK_CUSTOM_DICTIONARY_STORAGE_KEY_PREFIX}${languageCode}`;
  }

  getSpellcheckExcludedWordsStorageKey(languageCode) {
    return `${SPELLCHECK_EXCLUDED_WORDS_STORAGE_KEY_PREFIX}${languageCode}`;
  }

  normalizeSpellcheckCustomDictionaryWord(languageCode, word) {
    const normalizedLanguageCode =
      this.normalizeSpellcheckLanguage(languageCode);

    if (!normalizedLanguageCode) {
      return '';
    }

    return normalizeSpellcheckLookupWord(word, normalizedLanguageCode);
  }

  normalizeSpellcheckCustomDictionaryTimestamp(
    value,
    fallbackValue = Date.now(),
  ) {
    const normalizedValue = Number(value);

    if (Number.isFinite(normalizedValue) && normalizedValue > 0) {
      return normalizedValue;
    }

    const normalizedFallbackValue = Number(fallbackValue);

    if (
      Number.isFinite(normalizedFallbackValue) &&
      normalizedFallbackValue > 0
    ) {
      return normalizedFallbackValue;
    }

    return Date.now();
  }

  normalizeSpellcheckCustomDictionaryEntries(
    languageCode,
    entries,
    existingEntries = [],
  ) {
    const normalizedLanguageCode =
      this.normalizeSpellcheckLanguage(languageCode);

    if (!normalizedLanguageCode) {
      return [];
    }

    const fallbackAddedAt = Date.now();
    const existingEntriesByWord = new Map();
    const sourceExistingEntries = Array.isArray(existingEntries)
      ? existingEntries
      : [existingEntries];

    sourceExistingEntries.forEach((entry) => {
      const normalizedWord = this.normalizeSpellcheckCustomDictionaryWord(
        normalizedLanguageCode,
        typeof entry === 'string' ? entry : entry?.word,
      );

      if (!normalizedWord || existingEntriesByWord.has(normalizedWord)) {
        return;
      }

      existingEntriesByWord.set(normalizedWord, {
        word: normalizedWord,
        addedAt: this.normalizeSpellcheckCustomDictionaryTimestamp(
          entry && typeof entry === 'object' ? entry.addedAt : null,
          fallbackAddedAt,
        ),
      });
    });

    const normalizedEntries = new Map();
    const sourceEntries = Array.isArray(entries) ? entries : [entries];

    sourceEntries.forEach((entry) => {
      const normalizedWord = this.normalizeSpellcheckCustomDictionaryWord(
        normalizedLanguageCode,
        typeof entry === 'string' ? entry : entry?.word,
      );

      if (!normalizedWord || normalizedEntries.has(normalizedWord)) {
        return;
      }

      const existingEntry = existingEntriesByWord.get(normalizedWord);

      normalizedEntries.set(normalizedWord, {
        word: normalizedWord,
        addedAt: this.normalizeSpellcheckCustomDictionaryTimestamp(
          entry && typeof entry === 'object'
            ? entry.addedAt
            : existingEntry?.addedAt,
          existingEntry?.addedAt ?? fallbackAddedAt,
        ),
      });
    });

    return Array.from(normalizedEntries.values()).sort((left, right) =>
      left.word.localeCompare(right.word),
    );
  }

  normalizeSpellcheckCustomDictionaryWords(languageCode, words) {
    return this.normalizeSpellcheckCustomDictionaryEntries(
      languageCode,
      words,
    ).map(({ word }) => word);
  }

  normalizeSpellcheckExcludedWord(languageCode, word) {
    return this.normalizeSpellcheckCustomDictionaryWord(languageCode, word);
  }

  normalizeSpellcheckExcludedWordEntries(
    languageCode,
    entries,
    existingEntries = [],
  ) {
    return this.normalizeSpellcheckCustomDictionaryEntries(
      languageCode,
      entries,
      existingEntries,
    );
  }

  normalizeSpellcheckExcludedWords(languageCode, words) {
    return this.normalizeSpellcheckExcludedWordEntries(languageCode, words).map(
      ({ word }) => word,
    );
  }

  isSupportedSpellcheckCustomDictionaryVersion(version) {
    return (
      version === LEGACY_SPELLCHECK_CUSTOM_DICTIONARY_VERSION ||
      version === SPELLCHECK_CUSTOM_DICTIONARY_VERSION
    );
  }

  isSupportedSpellcheckExcludedWordsVersion(version) {
    return version === SPELLCHECK_EXCLUDED_WORDS_VERSION;
  }

  loadSpellcheckPreference(languageCode, defaultEnabled = false) {
    const normalizedLanguageCode =
      this.normalizeSpellcheckLanguage(languageCode);
    const fallbackValue = Boolean(defaultEnabled);

    if (!normalizedLanguageCode) {
      return fallbackValue;
    }

    try {
      const preferencesVersion = this.storage?.getItem(
        SPELLCHECK_PREFERENCES_VERSION_STORAGE_KEY,
      );

      if (preferencesVersion !== SPELLCHECK_PREFERENCES_VERSION) {
        if (normalizedLanguageCode === 'en') {
          const legacyValue = this.storage?.getItem(
            LEGACY_SPELLCHECK_STORAGE_KEY,
          );
          if (legacyValue === '1' || legacyValue === '0') {
            return legacyValue === '1';
          }
        }

        return fallbackValue;
      }

      const storedValue = this.storage?.getItem(
        this.getSpellcheckStorageKey(normalizedLanguageCode),
      );

      if (storedValue === '1' || storedValue === '0') {
        return storedValue === '1';
      }
    } catch (_error) {
      return fallbackValue;
    }

    return fallbackValue;
  }

  saveSpellcheckPreference(languageCode, enabled) {
    const normalizedLanguageCode =
      this.normalizeSpellcheckLanguage(languageCode);

    if (!normalizedLanguageCode) {
      return;
    }

    try {
      this.storage?.setItem(
        SPELLCHECK_PREFERENCES_VERSION_STORAGE_KEY,
        SPELLCHECK_PREFERENCES_VERSION,
      );
      this.storage?.setItem(
        this.getSpellcheckStorageKey(normalizedLanguageCode),
        enabled ? '1' : '0',
      );

      if (normalizedLanguageCode === 'en') {
        this.storage?.setItem(
          LEGACY_SPELLCHECK_STORAGE_KEY,
          enabled ? '1' : '0',
        );
      }
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  loadSpellcheckCustomDictionaryEntries(languageCode) {
    const normalizedLanguageCode =
      this.normalizeSpellcheckLanguage(languageCode);

    if (!normalizedLanguageCode) {
      return [];
    }

    try {
      const version = this.storage?.getItem(
        SPELLCHECK_CUSTOM_DICTIONARY_VERSION_STORAGE_KEY,
      );

      if (!this.isSupportedSpellcheckCustomDictionaryVersion(version)) {
        return [];
      }

      const storageKey = this.getSpellcheckCustomDictionaryStorageKey(
        normalizedLanguageCode,
      );
      const storedValue = this.storage?.getItem(storageKey);

      if (!storedValue) {
        return [];
      }

      const normalizedEntries = this.normalizeSpellcheckCustomDictionaryEntries(
        normalizedLanguageCode,
        JSON.parse(storedValue),
      );
      const normalizedStoredValue = JSON.stringify(normalizedEntries);

      if (
        version !== SPELLCHECK_CUSTOM_DICTIONARY_VERSION ||
        storedValue !== normalizedStoredValue
      ) {
        this.storage?.setItem(
          SPELLCHECK_CUSTOM_DICTIONARY_VERSION_STORAGE_KEY,
          SPELLCHECK_CUSTOM_DICTIONARY_VERSION,
        );

        if (normalizedEntries.length) {
          this.storage?.setItem(storageKey, normalizedStoredValue);
        } else {
          this.storage?.removeItem(storageKey);
        }
      }

      return normalizedEntries;
    } catch (_error) {
      return [];
    }
  }

  loadSpellcheckCustomDictionaryWords(languageCode) {
    return this.loadSpellcheckCustomDictionaryEntries(languageCode).map(
      ({ word }) => word,
    );
  }

  saveSpellcheckCustomDictionaryEntries(languageCode, entries) {
    const normalizedLanguageCode =
      this.normalizeSpellcheckLanguage(languageCode);

    if (!normalizedLanguageCode) {
      return [];
    }

    const normalizedEntries = this.normalizeSpellcheckCustomDictionaryEntries(
      normalizedLanguageCode,
      entries,
      this.loadSpellcheckCustomDictionaryEntries(normalizedLanguageCode),
    );

    try {
      this.storage?.setItem(
        SPELLCHECK_CUSTOM_DICTIONARY_VERSION_STORAGE_KEY,
        SPELLCHECK_CUSTOM_DICTIONARY_VERSION,
      );

      if (!normalizedEntries.length) {
        this.storage?.removeItem(
          this.getSpellcheckCustomDictionaryStorageKey(normalizedLanguageCode),
        );
        return normalizedEntries;
      }

      this.storage?.setItem(
        this.getSpellcheckCustomDictionaryStorageKey(normalizedLanguageCode),
        JSON.stringify(normalizedEntries),
      );
    } catch (_error) {
      // Ignore storage failures.
    }

    return normalizedEntries;
  }

  saveSpellcheckCustomDictionaryWords(languageCode, words) {
    return this.saveSpellcheckCustomDictionaryEntries(languageCode, words).map(
      ({ word }) => word,
    );
  }

  addSpellcheckCustomDictionaryWord(languageCode, word) {
    const normalizedLanguageCode =
      this.normalizeSpellcheckLanguage(languageCode);

    if (!normalizedLanguageCode) {
      return [];
    }

    const normalizedWord = this.normalizeSpellcheckCustomDictionaryWord(
      normalizedLanguageCode,
      word,
    );

    if (!normalizedWord) {
      return this.loadSpellcheckCustomDictionaryWords(normalizedLanguageCode);
    }

    return this.saveSpellcheckCustomDictionaryWords(
      normalizedLanguageCode,
      this.loadSpellcheckCustomDictionaryWords(normalizedLanguageCode).concat(
        normalizedWord,
      ),
    );
  }

  loadSpellcheckExcludedWordEntries(languageCode) {
    const normalizedLanguageCode =
      this.normalizeSpellcheckLanguage(languageCode);

    if (!normalizedLanguageCode) {
      return [];
    }

    try {
      const version = this.storage?.getItem(
        SPELLCHECK_EXCLUDED_WORDS_VERSION_STORAGE_KEY,
      );

      if (!this.isSupportedSpellcheckExcludedWordsVersion(version)) {
        return [];
      }

      const storageKey = this.getSpellcheckExcludedWordsStorageKey(
        normalizedLanguageCode,
      );
      const storedValue = this.storage?.getItem(storageKey);

      if (!storedValue) {
        return [];
      }

      const normalizedEntries = this.normalizeSpellcheckExcludedWordEntries(
        normalizedLanguageCode,
        JSON.parse(storedValue),
      );
      const normalizedStoredValue = JSON.stringify(normalizedEntries);

      if (storedValue !== normalizedStoredValue) {
        this.storage?.setItem(
          SPELLCHECK_EXCLUDED_WORDS_VERSION_STORAGE_KEY,
          SPELLCHECK_EXCLUDED_WORDS_VERSION,
        );

        if (normalizedEntries.length) {
          this.storage?.setItem(storageKey, normalizedStoredValue);
        } else {
          this.storage?.removeItem(storageKey);
        }
      }

      return normalizedEntries;
    } catch (_error) {
      return [];
    }
  }

  loadSpellcheckExcludedWords(languageCode) {
    return this.loadSpellcheckExcludedWordEntries(languageCode).map(
      ({ word }) => word,
    );
  }

  saveSpellcheckExcludedWordEntries(languageCode, entries) {
    const normalizedLanguageCode =
      this.normalizeSpellcheckLanguage(languageCode);

    if (!normalizedLanguageCode) {
      return [];
    }

    const normalizedEntries = this.normalizeSpellcheckExcludedWordEntries(
      normalizedLanguageCode,
      entries,
      this.loadSpellcheckExcludedWordEntries(normalizedLanguageCode),
    );

    try {
      this.storage?.setItem(
        SPELLCHECK_EXCLUDED_WORDS_VERSION_STORAGE_KEY,
        SPELLCHECK_EXCLUDED_WORDS_VERSION,
      );

      if (!normalizedEntries.length) {
        this.storage?.removeItem(
          this.getSpellcheckExcludedWordsStorageKey(normalizedLanguageCode),
        );
        return normalizedEntries;
      }

      this.storage?.setItem(
        this.getSpellcheckExcludedWordsStorageKey(normalizedLanguageCode),
        JSON.stringify(normalizedEntries),
      );
    } catch (_error) {
      // Ignore storage failures.
    }

    return normalizedEntries;
  }

  saveSpellcheckExcludedWords(languageCode, words) {
    return this.saveSpellcheckExcludedWordEntries(languageCode, words).map(
      ({ word }) => word,
    );
  }

  addSpellcheckExcludedWord(languageCode, word) {
    const normalizedLanguageCode =
      this.normalizeSpellcheckLanguage(languageCode);

    if (!normalizedLanguageCode) {
      return [];
    }

    const normalizedWord = this.normalizeSpellcheckExcludedWord(
      normalizedLanguageCode,
      word,
    );

    if (!normalizedWord) {
      return this.loadSpellcheckExcludedWords(normalizedLanguageCode);
    }

    return this.saveSpellcheckExcludedWords(
      normalizedLanguageCode,
      this.loadSpellcheckExcludedWords(normalizedLanguageCode).concat(
        normalizedWord,
      ),
    );
  }

  loadTranscriptLocalePreference(defaultLocale = '') {
    const fallbackValue =
      typeof defaultLocale === 'string' ? defaultLocale.trim() : '';

    try {
      const storedValue = this.storage?.getItem(TRANSCRIPT_LOCALE_STORAGE_KEY);

      return typeof storedValue === 'string'
        ? storedValue.trim()
        : fallbackValue;
    } catch (_error) {
      return fallbackValue;
    }
  }

  saveTranscriptLocalePreference(locale) {
    const normalizedLocale = typeof locale === 'string' ? locale.trim() : '';

    try {
      if (!normalizedLocale) {
        this.storage?.removeItem(TRANSCRIPT_LOCALE_STORAGE_KEY);
        return;
      }

      this.storage?.setItem(TRANSCRIPT_LOCALE_STORAGE_KEY, normalizedLocale);
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  loadTranscriptUploadApiKeyPreference(defaultValue = '') {
    const fallbackValue =
      typeof defaultValue === 'string' ? defaultValue.trim() : '';

    try {
      const storedValue = this.storage?.getItem(
        TRANSCRIPT_UPLOAD_API_KEY_STORAGE_KEY,
      );

      return typeof storedValue === 'string'
        ? storedValue.trim()
        : fallbackValue;
    } catch (_error) {
      return fallbackValue;
    }
  }

  saveTranscriptUploadApiKeyPreference(apiKey) {
    const normalizedApiKey = typeof apiKey === 'string' ? apiKey.trim() : '';

    try {
      if (!normalizedApiKey) {
        this.storage?.removeItem(TRANSCRIPT_UPLOAD_API_KEY_STORAGE_KEY);
        return;
      }

      this.storage?.setItem(
        TRANSCRIPT_UPLOAD_API_KEY_STORAGE_KEY,
        normalizedApiKey,
      );
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  getDefaultPreviewTypographyPreference() {
    return {
      ...DEFAULT_PREVIEW_TYPOGRAPHY,
    };
  }

  normalizePreviewTypographyPreference(value) {
    const normalizedValue = value && typeof value === 'object' ? value : {};
    const rawFontSize = Number.parseInt(
      String(
        normalizedValue.fontSizePx ??
          normalizedValue.fontSize ??
          DEFAULT_PREVIEW_TYPOGRAPHY.fontSizePx,
      ),
      10,
    );

    return {
      fontSizePx: Math.min(
        MAX_PREVIEW_FONT_SIZE_PX,
        Math.max(
          MIN_PREVIEW_FONT_SIZE_PX,
          Number.isFinite(rawFontSize)
            ? Math.round(rawFontSize)
            : DEFAULT_PREVIEW_TYPOGRAPHY.fontSizePx,
        ),
      ),
      fontFamily:
        typeof normalizedValue.fontFamily === 'string'
          ? normalizedValue.fontFamily.trim()
          : DEFAULT_PREVIEW_TYPOGRAPHY.fontFamily,
    };
  }

  loadPreviewTypographyPreference() {
    try {
      const rawValue = this.storage?.getItem(PREVIEW_TYPOGRAPHY_STORAGE_KEY);

      if (!rawValue) {
        return this.getDefaultPreviewTypographyPreference();
      }

      return this.normalizePreviewTypographyPreference(JSON.parse(rawValue));
    } catch (_error) {
      return this.getDefaultPreviewTypographyPreference();
    }
  }

  savePreviewTypographyPreference(value) {
    try {
      this.storage?.setItem(
        PREVIEW_TYPOGRAPHY_STORAGE_KEY,
        JSON.stringify(this.normalizePreviewTypographyPreference(value)),
      );
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  loadOpenLyricPluginEnabledPreference() {
    return loadOpenLyricPluginEnabledPreference(this.storage);
  }

  saveOpenLyricPluginEnabledPreference(enabled) {
    saveOpenLyricPluginEnabledPreference(
      normalizeOpenLyricPluginEnabledPreference(enabled),
      this.storage,
    );
  }

  normalizeEditorMode(mode) {
    return mode === 'simple' ? 'simple' : DEFAULT_EDITOR_MODE;
  }

  loadEditorModePreference() {
    try {
      const storedValue = this.storage?.getItem(EDITOR_MODE_STORAGE_KEY);

      return this.normalizeEditorMode(storedValue);
    } catch (_error) {
      return DEFAULT_EDITOR_MODE;
    }
  }

  saveEditorModePreference(mode) {
    try {
      this.storage?.setItem(
        EDITOR_MODE_STORAGE_KEY,
        this.normalizeEditorMode(mode),
      );
    } catch (_error) {
      // Ignore storage failures.
    }
  }

  normalizeTheme(theme) {
    if (isOpenLyricTheme(theme)) {
      return theme;
    }

    return DEFAULT_THEME;
  }

  loadStoredThemePreference() {
    try {
      const storedValue = this.storage?.getItem(THEME_STORAGE_KEY);

      if (isOpenLyricTheme(storedValue)) {
        return storedValue;
      }
    } catch (_error) {
      // Ignore storage failures.
    }

    try {
      const legacyStoredValue = this.storage?.getItem(LEGACY_THEME_STORAGE_KEY);

      // The legacy key predates the `-bs` palettes, so it only ever holds
      // `light` or `dark`; `isOpenLyricTheme` still reads it correctly.
      if (isOpenLyricTheme(legacyStoredValue)) {
        this.saveThemePreference(legacyStoredValue);
        return legacyStoredValue;
      }
    } catch (_error) {
      // Ignore storage failures.
    }

    return null;
  }

  hasStoredThemePreference() {
    return this.loadStoredThemePreference() !== null;
  }

  loadThemePreference() {
    const storedTheme = this.loadStoredThemePreference();

    if (storedTheme) {
      return storedTheme;
    }

    return DEFAULT_THEME;
  }

  saveThemePreference(theme) {
    try {
      this.storage?.setItem(THEME_STORAGE_KEY, this.normalizeTheme(theme));
    } catch (_error) {
      // Ignore storage failures.
    }
  }
}

export { EditorPreferencesStore };
