import { grammar } from './shared.ts';
import {
  getDictionaryPrefixSuggestions,
  getSuggestionDictionaryConfigs,
  loadDictionary,
  mergeDictionarySuggestions,
  normalizeWord,
} from './spellcheck-common.ts';

const {
  FORM_SECTION_NAMES,
  LYRIC_SECTION_NAMES,
  INSTRUMENTAL_SECTION_NAMES,
  FREE_TEXT_SECTION_NAMES,
  CONFIG_FIELD_NAMES,
} = grammar;

function createExtraWordSet() {
  const extraWords = ['ol', 'open', 'lyric', 'bpm'];
  const sectionWords = [
    ...FORM_SECTION_NAMES,
    ...LYRIC_SECTION_NAMES,
    ...INSTRUMENTAL_SECTION_NAMES,
    ...FREE_TEXT_SECTION_NAMES,
    ...CONFIG_FIELD_NAMES,
  ].flatMap((value) => value.split(/[\s\-]+/));

  return new Set(
    extraWords.concat(sectionWords).map((value) => value.toLowerCase()),
  );
}

const extraWords = createExtraWordSet();

function createEnglishSpellcheckProvider() {
  const checkCache = new Map();
  const prefixSuggestionCache = new Map();
  const suggestionCache = new Map();
  let dictionary = null;
  let loadPromise = null;
  let suggestionDictionaries = [];
  let suggestionLoadPromise = null;
  const suggestionDictionaryConfigs = getSuggestionDictionaryConfigs('en');

  function normalizeCacheKey(word) {
    return normalizeWord(word, 'en').toLowerCase();
  }

  function isIgnoredWord(word) {
    return extraWords.has(word.toLowerCase());
  }

  function shouldCheckWord(word) {
    const normalizedWord = normalizeWord(word, 'en');
    if (!normalizedWord || normalizedWord.length === 1) {
      return false;
    }

    return !isIgnoredWord(normalizedWord);
  }

  function isSpelledCorrectly(word) {
    const normalizedWord = normalizeWord(word, 'en');

    if (!dictionary?.loaded || !shouldCheckWord(normalizedWord)) {
      return true;
    }

    if (dictionary.check(normalizedWord)) {
      return true;
    }

    if (
      /^.+['’]s$/i.test(normalizedWord) &&
      dictionary.check(normalizedWord.slice(0, -2))
    ) {
      return true;
    }

    if (
      /^.+s['’]$/i.test(normalizedWord) &&
      dictionary.check(normalizedWord.slice(0, -1))
    ) {
      return true;
    }

    const contractionMatch = normalizedWord.match(
      /^(.*?)(?:n't|'re|'ve|'ll|'d|'m)$/i,
    );
    if (contractionMatch && dictionary.check(contractionMatch[1])) {
      return true;
    }

    return false;
  }

  async function initialize() {
    if (dictionary?.loaded) {
      return true;
    }

    if (!loadPromise) {
      loadPromise = loadDictionary('en')
        .then((nextDictionary) => {
          dictionary = nextDictionary?.loaded ? nextDictionary : null;
          if (!dictionary) {
            console.error(
              'English spellcheck dictionary did not finish loading.',
            );
            return false;
          }

          return true;
        })
        .catch((error) => {
          console.error('Failed to initialize English spellcheck.', error);
          loadPromise = null;
          return false;
        });
    }

    return loadPromise;
  }

  async function initializeSuggestionDictionaries() {
    if (!suggestionDictionaryConfigs.length) {
      return [];
    }

    if (
      suggestionDictionaries.length === suggestionDictionaryConfigs.length &&
      suggestionDictionaries.every((entry) => entry?.loaded)
    ) {
      return suggestionDictionaries;
    }

    if (!suggestionLoadPromise) {
      suggestionLoadPromise = Promise.allSettled(
        suggestionDictionaryConfigs.map((dictionaryConfig) =>
          loadDictionary(dictionaryConfig),
        ),
      ).then((results) => {
        const loadedSuggestionDictionaries = [];

        results.forEach((result, index) => {
          if (result.status === 'fulfilled' && result.value?.loaded) {
            loadedSuggestionDictionaries.push(result.value);
            return;
          }

          if (result.status === 'rejected') {
            console.error(
              `Failed to initialize English spellcheck suggestion dictionary ${index + 1}.`,
              result.reason,
            );
            return;
          }

          console.error(
            `English spellcheck suggestion dictionary ${index + 1} did not finish loading.`,
          );
        });

        suggestionDictionaries = loadedSuggestionDictionaries;
        return suggestionDictionaries;
      });
    }

    return suggestionLoadPromise;
  }

  async function getSuggestionSources() {
    if (suggestionDictionaryConfigs.length) {
      const loadedSuggestionDictionaries =
        await initializeSuggestionDictionaries();
      if (loadedSuggestionDictionaries.length) {
        return loadedSuggestionDictionaries;
      }
    }

    const ready = await initialize();
    return ready && dictionary?.loaded ? [dictionary] : [];
  }

  async function checkWords(words) {
    const results = new Map();
    const uniqueWords = Array.from(new Set(words));

    if (!uniqueWords.length) {
      return results;
    }

    const ready = await initialize();
    if (!ready || !dictionary?.loaded) {
      uniqueWords.forEach((word) => {
        results.set(word, true);
      });
      return results;
    }

    uniqueWords.forEach((word) => {
      if (!shouldCheckWord(word)) {
        results.set(word, true);
        return;
      }

      const cacheKey = normalizeCacheKey(word);
      if (!checkCache.has(cacheKey)) {
        checkCache.set(cacheKey, isSpelledCorrectly(word));
      }

      results.set(word, checkCache.get(cacheKey) ?? true);
    });

    return results;
  }

  async function getSuggestions(word) {
    const normalizedWord = normalizeWord(word, 'en');
    if (!normalizedWord) {
      return [];
    }

    const suggestionSources = await getSuggestionSources();
    if (!suggestionSources.length) {
      return [];
    }

    const cacheKey = normalizeCacheKey(word);
    if (!suggestionCache.has(cacheKey)) {
      suggestionCache.set(
        cacheKey,
        mergeDictionarySuggestions(suggestionSources, normalizedWord, 3),
      );
    }

    return suggestionCache.get(cacheKey) || [];
  }

  async function getPrefixSuggestions(word, limit = 8) {
    const normalizedWord = normalizeCacheKey(word);
    const maxSuggestions = Math.max(1, Number(limit) || 8);

    if (!shouldCheckWord(normalizedWord)) {
      return [];
    }

    const suggestionSources = await getSuggestionSources();
    if (!suggestionSources.length) {
      return [];
    }

    const cacheKey = `${normalizedWord}::${maxSuggestions}`;
    if (!prefixSuggestionCache.has(cacheKey)) {
      prefixSuggestionCache.set(
        cacheKey,
        getDictionaryPrefixSuggestions(
          suggestionSources,
          normalizedWord,
          maxSuggestions,
        ),
      );
    }

    return prefixSuggestionCache.get(cacheKey) || [];
  }

  function dispose() {
    checkCache.clear();
    prefixSuggestionCache.clear();
    suggestionCache.clear();
    dictionary = null;
    loadPromise = null;
    suggestionDictionaries = [];
    suggestionLoadPromise = null;
  }

  return {
    languageCode: 'en',
    checkWords,
    dispose,
    getPrefixSuggestions,
    getSuggestions,
    initialize,
    isReady: () => Boolean(dictionary?.loaded),
    shouldCheckWord,
  };
}

export { createEnglishSpellcheckProvider };
